float invSqrt(float x) {
  if (x <= 0.0f) return 0.0f;
  float xhalf = 0.5f * x;
  int32_t i;
  memcpy(&i, &x, sizeof(i));
  i = 0x5f3759df - (i >> 1);
  float y;
  memcpy(&y, &i, sizeof(y));
  return y * (1.5f - (xhalf * y * y));
}

